'use strict';

// Чиста логіка, спільна для openHAB і тестів Node.js. Час передається явно.
class Monitor {
  constructor(now) {
    this.started = now;
    this.sensors = ['cold', 'hot', 'humidity', 'leak', 'door', 'ups'];
    this.lastSeen = Object.fromEntries(this.sensors.map(name => [name, null]));
    this.offlineSince = Object.fromEntries(this.sensors.map(name => [name, null]));
  }

  seen(device, now) {
    this.lastSeen[device] = now;
  }

  evaluate(input, now) {
    const missing = [];
    for (const name of this.sensors) {
      if (input[name + 'Status'] === 'online') {
        this.offlineSince[name] = null;
      } else if (this.offlineSince[name] === null) {
        this.offlineSince[name] = now;
      }
      const offline = this.offlineSince[name];
      const last = this.lastSeen[name] === null ? this.started : this.lastSeen[name];
      if ((offline !== null && now - offline > 60000) || now - last > 60000) {
        missing.push(name);
      }
    }
    const hot = Number.isFinite(input.hot) ? input.hot : null;
    const critical = hot !== null && hot > 40;
    const heat = hot !== null && hot > 35;
    const water = input.leak === 'ON';
    const ups = input.upsMode === 'BATTERY' && Number.isFinite(input.battery) && input.battery < 30;
    const messages = [];
    if (critical) messages.push('КРИТИЧНО: гарячий коридор > 40 °C');
    else if (heat) messages.push('Перегрів: кондиціонер на максимум');
    if (water) messages.push('ПРОТІКАННЯ: перевірте серверну');
    if (ups) messages.push('Підготувати сервери до вимкнення');
    if (missing.length) messages.push('Немає даних: ' + missing.join(', '));
    const alarm = critical || water || ups || missing.length > 0;
    return {
      heat, critical, water, ups, missing, alarm,
      siren: alarm ? 'ON' : 'OFF',
      light: alarm ? 'RED' : heat ? 'YELLOW' : 'GREEN',
      message: messages.length ? messages.join(' | ') : 'Норма',
      // Між 33 і 35 °C зберігаємо стан: гістерезис проти частого перемикання.
      ac: heat ? { state: 'ON', mode: 'MAX' } :
        hot !== null && hot < 33 ? { state: 'OFF', mode: 'NORMAL' } : null
    };
  }
}

module.exports = { Monitor };
